    {
      name: "engineering",
      skills: "./AGENTS.md",
      hooks: "./hooks/hooks.json",
    },
    claudeAdapter,
    "plugins/engineering/.claude-plugin/plugin.json",
    "engineering",
  );

  expect(failures.some((failure) => /AGENTS\.md/i.test(failure.message))).toBe(true);
});
"}

